const scene=document.querySelector('#scene'),el={role:document.querySelector('#roleTag'),eyebrow:document.querySelector('#eyebrow'),title:document.querySelector('#title'),narration:document.querySelector('#narration'),speaker:document.querySelector('#speaker'),line:document.querySelector('#line'),choices:document.querySelector('#choices'),hint:document.querySelector('#hint'),clock:document.querySelector('#clockCard'),chapter:document.querySelector('#chapterLabel')};
const S={
intro:['intro','짧은 감정 어드벤처','CH. 01 · 또 깜빡했어','오늘을 다시 고를 수 있다면','오늘 저녁, 엄마와 나는 준비물 때문에 조금 크게 다퉜다. 이 이야기를 끝까지 보면 오늘 저녁으로 한 번 돌아갈 수 있다.','','당신은 초등학교 2학년 도윤입니다. 내일 미술 시간에 쓸 색종이를 챙겨야 해요.',[['도윤의 저녁 시작하기','child','primary']],'선택에 정답은 없어요. 다만 같은 순간을 다른 마음으로 다시 볼 수 있어요.'],
child:['child','지금 당신은 · 도윤','저녁 7시 40분 · 식탁','가방을 열어 볼까?','숙제 공책은 식탁 위에 펴져 있다. 가방은 의자에 걸려 있고, 내일 준비물은 아직 확인하지 않았다.','엄마','“도윤아, 내일 준비물도 가방에 넣었어?”',[['“잠깐만. 가방 열어서 볼게.”','check','primary'],['“응, 챙겼어.”','skip'],['“준비물은 내일의 내가 챙기겠지!”','silly','silly']],'도윤은 지금 귀찮고, 엄마는 내일 아침이 또 바빠질까 걱정돼요.'],
check:['child','지금 당신은 · 도윤','저녁 7시 41분 · 식탁','알림장이 구겨져 있다','가방 앞주머니에서 알림장이 나왔다. “색종이, 풀, 자.” 그런데 풀은 다 썼다.','도윤','“아… 풀도 없네. 내일 아침에 말하면 늦겠지?”',[['“엄마, 내일 문구점 들러야 해. 메모해 줄래?”','mother','primary'],['“없는 풀로 숙제가 스스로 붙으면 좋겠다.”','silly2','silly']],'미리 알아차렸어도 모두 혼자 해결할 필요는 없어요.'],
skip:['child','지금 당신은 · 도윤','다음 날 아침 · 현관','문 앞에서 멈춘 하루','신발을 신다가 알림장을 봤다. 가방 안에는 공책과 연필뿐이다.','엄마','“어제 챙겼다고 했잖아. 왜 매번 마지막에 알게 되는 걸까?”',[['아무 말 없이 고개를 숙인다.','mother'],['“엄마도 어제 확인 안 했잖아!”','mother']],'두 사람 모두 자기 몫의 피곤함만 보이기 시작했어요.'],
silly:['child','상상 속 · 내일의 도윤','미래에서 온 항의','내일의 내가 화났다','잠옷을 입은 내일의 도윤이 현관에서 나타났다. 한 손엔 빈 가방, 다른 손엔 “왜 나한테 넘겼어?”라고 쓴 쪽지.','내일의 도윤','“나는 미래에서 왔어. 그런데 준비물은 같이 안 왔어!”',[['그래도 가방을 열어서 확인해 본다.','check','primary']],'내일의 나는 대신 해결해 주지 않아요.'],
silly2:['child','상상 속 · 풀의 반란','식탁 위의 작은 목소리','빈 풀통이 말했다','빈 풀통이 데굴데굴 굴러가더니 말한다. “나는 텅 비었어. 내일 아침의 너도 바쁠 텐데?”','도윤','“알겠어. 지금 말할게.”',[['엄마에게 필요한 것을 말한다.','mother','primary']],'상상은 쉬게 해 주지만, 해결은 작은 말 한마디에서 시작돼요.'],
mother:['mother','이제 당신은 · 엄마','같은 저녁 · 엄마의 시간','엄마도 놓친 것이 있다','엄마는 저녁을 치우고, 빨래를 널고, 내일 아침을 생각하고 있었다. “챙겼어?”라고 물었지만 가방을 함께 열어 보지는 않았다.','엄마의 마음','“왜 또 깜빡했냐고 묻기 전에, 같이 확인할 방법을 만들 수도 있었는데.”',[['마음의 시계를 돌린다.','rewind','primary']],'깜빡한 일은 아이 혼자 만든 문제가 아닐 수 있어요. 기억에만 맡긴 방식도 함께 바꿀 수 있어요.'],
rewind:['rewind','마음의 시계 · 한 번 더','저녁 7시 40분으로 돌아왔다','다시 말할 수 있다면','이번에는 엄마도, 도윤도 조금 더 알고 있다. 필요한 것은 더 착한 대답이 아니라, 실제로 해 볼 수 있는 방법이다.','엄마','“챙겼어? 말로 대답하기보다, 가방 열고 세 가지만 같이 볼까?”',[['“응. 알림장 보고 내가 먼저 넣어 볼게.”','ending','primary'],['“엄마가 다 찾아서 넣어 줘.”','help'],['“내일의 나에게 또 맡길래!”','silly','silly']],'좋은 선택은 완벽한 대답이 아니라, 다음번에 할 수 있는 작은 행동이에요.'],
help:['rewind','마음의 시계 · 한 번 더','다시 말한 뒤','함께, 하지만 대신은 아니게','엄마는 필요한 물건을 식탁에 올려 두고, 도윤에게 알림장을 읽어 달라고 했다. 마지막으로 가방에 넣는 손은 도윤의 손이었다.','엄마','“오늘은 같이 하자. 내일부터는 네가 현관 체크표를 보고 먼저 해 볼래?”',[['“응. 알림장, 준비물, 물통 세 칸으로 할래.”','ending','primary']],''],
ending:['ending','오늘의 끝','내일을 위한 세 칸','완벽하지 않아도, 다시 해 본다','가방 옆에 작은 체크표가 놓였다. 알림장 · 준비물 · 물통. 누구도 혼나지 않았지만, 내일을 위한 방법 하나가 생겼다.','도윤과 엄마','“아까는 미안해.”  “나도 말이 너무 컸어.”',[['다른 선택도 해 보기','intro','primary']],'현실에서는 시간을 되돌릴 수 없어요. 그래도 “아까는 미안해”와 “이번엔 같이 확인하자”는 언제든 다시 말할 수 있어요.']};
function render(k){const d=S[k];scene.className='scene '+d[0];el.role.textContent=d[1];el.eyebrow.textContent=d[2];el.title.textContent=d[3];el.narration.textContent=d[4];el.speaker.textContent=d[5];el.line.textContent=d[6];el.hint.textContent=d[8];el.clock.hidden=!['mother','rewind','help','ending'].includes(k);el.chapter.textContent=d[0]==='mother'?'CH. 01 · 엄마의 시간':d[0]==='rewind'?'CH. 01 · 다시 선택하기':'CH. 01 · 또 깜빡했어';el.choices.innerHTML='';d[7].forEach(([a,n,t])=>{let b=document.createElement('button');b.type='button';b.className='choice '+(t||'');b.textContent=a;b.onclick=()=>render(n);el.choices.append(b)});window.scrollTo({top:0,behavior:'smooth'})}document.querySelector('#restart').onclick=()=>render('intro');render('intro');
